import { useState } from 'react'
import { useParams } from 'react-router-dom'
import { useQuery } from '@tanstack/react-query'
import { clsx } from 'clsx'
import { LayoutGrid, List, Columns, Share2 } from 'lucide-react'
import { objectivesService } from '@/integrations/supabase/objectives'

type ViewMode = 'board' | 'list' | 'kanban' | 'graph'
const STATUSES = ['draft', 'open', 'assigned', 'in_progress', 'under_evaluation', 'completed']

export function NavigatorPage() {
  const { projectId } = useParams()
  const [view, setView] = useState<ViewMode>('list')

  const { data: objectives = [], isLoading } = useQuery({
    queryKey: ['objectives', projectId],
    queryFn: () => objectivesService.listObjectives(projectId ?? ''),
    enabled: !!projectId,
  })

  return (
    <div className="h-full flex flex-col overflow-hidden">
      <div className="flex items-center gap-2 p-4 border-b border-border bg-surface">
        <span className="text-sm font-medium mr-2">View:</span>
        {([
          { id: 'board', icon: <LayoutGrid size={14} /> },
          { id: 'list', icon: <List size={14} /> },
          { id: 'kanban', icon: <Columns size={14} /> },
          { id: 'graph', icon: <Share2 size={14} /> },
        ] as { id: ViewMode; icon: React.ReactNode }[]).map((v) => (
          <button key={v.id} onClick={() => setView(v.id)}
            className={clsx('flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs border transition-colors',
              view === v.id ? 'border-accent bg-accent/10 text-accent' : 'border-border text-muted-foreground hover:text-foreground')}>
            {v.icon} {v.id.charAt(0).toUpperCase() + v.id.slice(1)}
          </button>
        ))}
      </div>
      <div className="flex-1 overflow-auto p-4">
        {isLoading ? (
          <p className="text-sm text-muted-foreground">Loading…</p>
        ) : objectives.length === 0 ? (
          <div className="rounded-xl border border-dashed border-border p-10 text-center">
            <p className="text-sm text-muted-foreground">No objectives yet</p>
          </div>
        ) : (
          <>
            {view === 'list' && (
              <div className="max-w-3xl mx-auto flex flex-col gap-2">
                {objectives.map((obj) => (
                  <div key={obj.id} className="flex items-center gap-3 rounded-xl border border-border bg-surface px-4 py-3">
                    <span className="w-2 h-2 rounded-full bg-accent flex-shrink-0" />
                    <span className="text-sm flex-1">{obj.title}</span>
                    <span className="text-xs text-muted-foreground capitalize">{obj.status.replace('_', ' ')}</span>
                  </div>
                ))}
              </div>
            )}
            {view === 'kanban' && (
              <div className="flex gap-4 overflow-x-auto h-full pb-4">
                {STATUSES.map((status) => (
                  <div key={status} className="flex-shrink-0 w-60">
                    <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide mb-2 px-1">{status.replace('_', ' ')}</p>
                    <div className="flex flex-col gap-2">
                      {objectives.filter((o) => o.status === status).map((obj) => (
                        <div key={obj.id} className="bg-surface rounded-lg border border-border p-3 text-sm">{obj.title}</div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            )}
            {view === 'board' && (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                {objectives.map((obj) => (
                  <div key={obj.id} className="bg-surface rounded-xl border border-border p-4">
                    <p className="text-sm font-medium">{obj.title}</p>
                    <p className="text-xs text-muted-foreground mt-1 capitalize">{obj.status.replace('_', ' ')}</p>
                    <div className="flex items-center justify-between mt-3 text-xs text-muted-foreground">
                      <span>{obj.completedTasksCount}/{obj.tasksCount} tasks</span>
                      <span>{obj.participants?.length ?? 0} members</span>
                    </div>
                  </div>
                ))}
              </div>
            )}
            {view === 'graph' && (
              <div className="relative h-full min-h-[420px] rounded-xl border border-dashed border-border bg-surface overflow-hidden">
                <svg className="absolute inset-0 w-full h-full" preserveAspectRatio="none">
                  {objectives.slice(0, -1).map((_, i) => {
                    const x1 = 80 + (i % 4) * 160; const y1 = 80 + Math.floor(i / 4) * 120
                    const x2 = 80 + ((i + 1) % 4) * 160; const y2 = 80 + Math.floor((i + 1) / 4) * 120
                    return <line key={i} x1={x1} y1={y1} x2={x2} y2={y2} stroke="hsl(var(--border))" strokeWidth="1" />
                  })}
                </svg>
                {objectives.map((obj, i) => (
                  <div key={obj.id} className="absolute rounded-full bg-accent/10 border border-accent/50 text-accent text-xs px-3 py-1.5 -translate-x-1/2 -translate-y-1/2"
                    style={{ left: 80 + (i % 4) * 160, top: 80 + Math.floor(i / 4) * 120 }}>
                    {obj.title.slice(0, 24)}
                  </div>
                ))}
              </div>
            )}
          </>
        )}
      </div>
    </div>
  )
}
